  "settings.confirmations.clublog.password.hint": "Ein ClubLog <b>Application Password</b> verwenden (Settings → App Passwords), nicht Ihr Hauptpasswort. Im Schlüsselbund des Betriebssystems gespeichert.",
  "settings.confirmations.clublog.apiKey.label": "ClubLog-API-Schlüssel (auf Anwendungsebene)",
